using System;
using System.Collections.Generic;
using UnityEngine;

namespace TungSahur.FX
{
    public enum FXType { HitSpark, WoodChips, StrawBurst, Dust, DustSmall, SlamRing, SlamDebris, LandDust, ChargeFlash, Explosion, BombPop, Smoke }

    /// <summary>Pooled particle effects keyed by type. Prefabs are generated by the builder.</summary>
    public class FXManager : MonoBehaviour
    {
        [Serializable]
        public struct Entry
        {
            public FXType type;
            public ParticleSystem prefab;
            public int prewarm;
        }

        public Entry[] effects = Array.Empty<Entry>();
        public static FXManager Instance { get; private set; }

        readonly Dictionary<FXType, Queue<ParticleSystem>> pools = new();
        readonly Dictionary<FXType, ParticleSystem> prefabs = new();

        void Awake()
        {
            Instance = this;
            foreach (var e in effects)
            {
                if (e.prefab == null) continue;
                prefabs[e.type] = e.prefab;
                var q = new Queue<ParticleSystem>();
                pools[e.type] = q;
                for (int i = 0; i < Mathf.Max(1, e.prewarm); i++) q.Enqueue(Create(e.type));
            }
        }

        void OnDestroy() { if (Instance == this) Instance = null; }

        ParticleSystem Create(FXType t)
        {
            var ps = Instantiate(prefabs[t], transform);
            ps.gameObject.SetActive(false);
            return ps;
        }

        public static ParticleSystem Spawn(FXType type, Vector3 pos, Quaternion rot, float scale = 1f)
        {
            if (Instance == null || !Instance.prefabs.ContainsKey(type)) return null;
            var q = Instance.pools[type];
            ParticleSystem ps = null;
            // reuse the first finished instance
            int n = q.Count;
            for (int i = 0; i < n; i++)
            {
                var c = q.Dequeue();
                q.Enqueue(c);
                if (!c.gameObject.activeSelf || !c.IsAlive(true)) { ps = c; break; }
            }
            if (ps == null)
            {
                ps = Instance.Create(type);
                q.Enqueue(ps);
            }
            ps.transform.SetPositionAndRotation(pos, rot);
            ps.transform.localScale = Vector3.one * scale;
            if (ps.gameObject.activeSelf) ps.gameObject.SetActive(false);   // re-run OnEnable (flash lights)
            ps.gameObject.SetActive(true);
            ps.Clear(true);
            ps.Play(true);
            return ps;
        }
    }
}
